package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.graphics.Rect;
import android.os.*;
import android.view.*;
import android.view.accessibility.AccessibilityNodeInfo;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.runner.lifecycle.*;
import androidx.test.uiautomator.*;
import org.json.JSONObject;
import org.junit.Test;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.Assert.*;

/** Real private persistence and native report navigation; synthetic evidence, no capture or outputs. */
public final class SonarReportFlowTest {
    private final Instrumentation instrumentation=InstrumentationRegistry.getInstrumentation();
    private final Context context=instrumentation.getTargetContext();
    private final UiDevice device=UiDevice.getInstance(instrumentation);
    private static final String LABEL="VISUAL TEST · isolated synthetic sonar intervals";

    private boolean ready(Activity activity,View root){return !activity.isDestroyed()&&!activity.isFinishing()&&ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED).contains(activity)&&activity.getWindow().getDecorView()==root&&activity.hasWindowFocus()&&root.hasWindowFocus()&&root.isAttachedToWindow()&&root.isLaidOut()&&root.getWidth()>0&&root.getHeight()>0;}
    private <T extends Activity>T focused(Class<T> type)throws Exception{long until=SystemClock.elapsedRealtime()+8000;Activity[] found={null};while(found[0]==null&&SystemClock.elapsedRealtime()<until){instrumentation.runOnMainSync(()->{for(Activity activity:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(type.isInstance(activity)&&ready(activity,activity.getWindow().getDecorView()))found[0]=activity;});if(found[0]==null)SystemClock.sleep(40);}assertNotNull("Focused "+type.getSimpleName(),found[0]);return type.cast(found[0]);}
    private RecordReportActivity focusedReport(long id)throws Exception{long until=SystemClock.elapsedRealtime()+8000;RecordReportActivity[] found={null};while(found[0]==null&&SystemClock.elapsedRealtime()<until){instrumentation.runOnMainSync(()->{for(Activity activity:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(activity instanceof RecordReportActivity&&activity.getIntent().getLongExtra("record",0)==id&&ready(activity,activity.getWindow().getDecorView())){assertNull("Only one focused report for this record",found[0]);found[0]=(RecordReportActivity)activity;}});if(found[0]==null)SystemClock.sleep(40);}assertNotNull("Focused report for record "+id,found[0]);return found[0];}
    private View named(View root,String name){if(name.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View child=named(group.getChildAt(n),name);if(child!=null)return child;}return null;}
    private RecordChart chart(View root){if(root instanceof RecordChart)return(RecordChart)root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){RecordChart child=chart(group.getChildAt(n));if(child!=null)return child;}return null;}
    private int chartCount(View root){int total=root instanceof RecordChart?1:0;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++)total+=chartCount(group.getChildAt(n));return total;}
    private void complete(View view,String name){assertNotNull(name,view);Rect visible=new Rect(),frame=new Rect();assertTrue(name+" visible",view.getGlobalVisibleRect(visible));view.getRootView().getWindowVisibleDisplayFrame(frame);assertEquals(name+" full width",view.getWidth(),visible.width());assertEquals(name+" full height",view.getHeight(),visible.height());assertTrue(name+" above window bottom",visible.bottom<=frame.bottom);assertTrue(name+" below window top",visible.top>=frame.top);}
    private void click(String name)throws Exception{UiObject2 found=device.wait(Until.findObject(By.desc(name).enabled(true)),5000);if(found==null)found=device.wait(Until.findObject(By.text(name).enabled(true)),3000);assertNotNull("Actual enabled control: "+name,found);assertTrue(name+" retains touch target",found.getVisibleBounds().height()>=Design.dp(context,40));found.click();device.waitForIdle();}
    private void signals()throws Exception{focused(RecordReportActivity.class);assertTrue(device.wait(Until.hasObject(By.desc("Report options")),5000));click("Report options");assertTrue(device.wait(Until.hasObject(By.text("More about this night")),3000));click("Recorded signals & notes");assertTrue(device.wait(Until.hasObject(By.text("Signal quality")),5000));focused(RecordSignalsActivity.class);}
    private void signalBounds(RecordSignalsActivity owner,long start,long end){instrumentation.runOnMainSync(()->{View root=owner.getWindow().getDecorView();assertTrue(ready(owner,root));assertEquals("Only actually measured echo is plotted",1,chartCount(root));RecordChart plot=chart(root);complete(plot,"Relative echo chart");assertEquals("Relative echo change chart. 1 actual readings. Missing intervals are blank. Dense bars average contiguous readings.",plot.getContentDescription().toString());complete(named(root,"Recorded interval "+start+" to "+end+" in "+java.time.ZoneId.systemDefault().getId()),"Actual saved clock interval");for(String quality:new String[]{"Calibrating · 5 sec","Measured · 5 sec","No echo · 5 sec","Not recorded · 5 sec"})complete(named(root,quality),quality);});assertFalse(device.hasObject(By.text("Room noise")));assertFalse(device.hasObject(By.text("Room light")));assertFalse(device.hasObject(By.text("Phone movement")));assertFalse(device.hasObject(By.textStartsWith("Play recorded sound")));assertTrue(device.hasObject(By.text("Saved intervals · up to 5 seconds")));}
    private void capture(Activity owner,String name)throws Exception{long until=SystemClock.elapsedRealtime()+8000;boolean committed=false;while(!committed&&SystemClock.elapsedRealtime()<until){CountDownLatch frame=new CountDownLatch(1);View[] root={null};instrumentation.runOnMainSync(()->{View decor=owner.getWindow().getDecorView();if(ready(owner,decor)){assertTrue("Actual hardware-rendered native frame",decor.isHardwareAccelerated());root[0]=decor;decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();}});if(root[0]==null){SystemClock.sleep(40);continue;}if(!frame.await(1,TimeUnit.SECONDS))continue;device.waitForIdle();boolean[] valid={false};instrumentation.runOnMainSync(()->valid[0]=ready(owner,root[0]));committed=valid[0];}assertTrue("Focused attached frame "+name,committed);assertEquals("Capture stays in the isolated labelled fixture",LABEL,owner.getIntent().getStringExtra("verificationLabel"));if(!name.equals("supporting-routes"))assertTrue(device.hasObject(By.text(LABEL)));File folder=new File(context.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"sonar-report-"+name+".png")));}
    private void destroyed(Activity activity){long until=SystemClock.elapsedRealtime()+8000;while(!activity.isDestroyed()&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(40);assertTrue("Activity finished before reopening",activity.isDestroyed());}
    private void diagnose(Throwable original){File folder=new File(context.getExternalFilesDir(null),"verification");folder.mkdirs();try(PrintWriter writer=new PrintWriter(new File(folder,"sonar-report-error.txt"))){original.printStackTrace(writer);}catch(Exception error){original.addSuppressed(error);}try{device.dumpWindowHierarchy(new File(folder,"sonar-report-failure.xml"));device.takeScreenshot(new File(folder,"sonar-report-failure.png"));}catch(Exception error){original.addSuppressed(error);}}

    @Test public void savedSonarQualityZeroAndMissingIntervalsSurviveRealReportNavigation()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(TrackingService.running);assertFalse(AlarmService.active);assertFalse(Prefs.flag(context,"ringing"));
        String database="sonar-report-"+UUID.randomUUID()+".db",config=SensorProvenance.sonar(SonarConfig.defaults(),"UNPROCESSED");Records.Factory previous=Records.factory;Map<String,?> prefs=new HashMap<>(Prefs.of(context).getAll());List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)context.getApplicationContext();
        Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity activity,Bundle state){owned.add(activity);assertTrue("Report journey must never launch capture or alarm activities",activity instanceof RecordReportActivity||activity instanceof RecordSignalsActivity||activity instanceof EchoPeriodsActivity);}public void onActivityStarted(Activity activity){}public void onActivityResumed(Activity activity){}public void onActivityPaused(Activity activity){}public void onActivityStopped(Activity activity){}public void onActivitySaveInstanceState(Activity activity,Bundle state){}public void onActivityDestroyed(Activity activity){}};app.registerActivityLifecycleCallbacks(lifecycle);
        boolean cleaned=false;
        try{
            Records.factory=c->new Store(c,database);long id,start,end,legacyId,errorId;String fingerprint,raw;
            try(Store store=new Store(context,database)){
                store.getWritableDatabase().execSQL("INSERT INTO sessions(id,start,end,active_ms,note,source,origin,zone) VALUES(800,1000,3000,2000,'Original isolated row, must remain unchanged','legacy','legacy','UTC')");
                store.epoch(800,1000L,3000,.3,.2,4d,25);
                id=store.begin(SensorProvenance.SONAR,config,SoundAnalysisProvenance.encode(SoundAnalysisStatus.initial(true)));start=store.rows("SELECT start FROM sessions WHERE id=?",""+id).get(0).getLong("start");end=start+20000;
                store.sonarCheckpoint(id,start,start+5000,null,"CALIBRATING",125,5000);store.sonarCheckpoint(id,start+5000,start+10000,0d,"VALID",125,10000);store.sonarCheckpoint(id,start+10000,start+15000,null,"NO_ECHO",0,15000);store.end(id,false,15000,end,SoundAnalysisProvenance.encode(new SoundAnalysisStatus(true,"complete",1,"")));
                // Synthetic historical status fixtures verify report semantics, not actual model accuracy.
                errorId=store.begin(SensorProvenance.SONAR,config,SoundAnalysisProvenance.encode(SoundAnalysisStatus.initial(true)));long errorStart=store.rows("SELECT start FROM sessions WHERE id=?",""+errorId).get(0).getLong("start");store.sonarCheckpoint(errorId,errorStart,errorStart+5000,0d,"VALID",125,5000);store.end(errorId,false,5000,errorStart+5000,SoundAnalysisProvenance.encode(new SoundAnalysisStatus(true,"error",0,"model")));
                legacyId=store.begin(SensorProvenance.SONAR,config);long legacyStart=store.rows("SELECT start FROM sessions WHERE id=?",""+legacyId).get(0).getLong("start");store.sonarCheckpoint(legacyId,legacyStart,legacyStart+5000,0d,"VALID",125,5000);store.end(legacyId,false,5000,legacyStart+5000);store.getWritableDatabase().execSQL("UPDATE sessions SET sound_analysis='' WHERE id=?",new Object[]{legacyId});
                fingerprint=BackupFingerprint.read(store);raw=store.rows("SELECT * FROM epochs ORDER BY time").toString();assertEquals(4,Records.all(store).size());
            }
            context.startActivity(new Intent(context,RecordReportActivity.class).putExtra("record",id).putExtra("visualReview",true).putExtra("verificationLabel",LABEL).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));RecordReportActivity report=focusedReport(id);assertTrue(device.wait(Until.hasObject(By.text("Contactless movement")),5000));assertTrue(device.wait(Until.hasObject(By.text("Sound analysis completed.")),5000));assertTrue(device.hasObject(By.text("No classified sound events in this period.")));
            instrumentation.runOnMainSync(()->{View root=report.getWindow().getDecorView();complete(named(root,"Report options"),"Report options");complete(chart(root),"Saved sonar report chart");assertTrue(chart(root).getContentDescription().toString().startsWith("Relative echo change chart. 1 actual readings."));});capture(report,"night");
            signals();RecordSignalsActivity first=focused(RecordSignalsActivity.class);signalBounds(first,start,end);capture(first,"signals");
            // The same read-only journey exposes the real supporting routes, not a mock row.
            new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().description("Dream diary"));device.waitForIdle();
            instrumentation.runOnMainSync(()->{for(String name:new String[]{"Breathing rhythm","Sound events","Timed dream cues","Dream diary"}){View target=named(first.getWindow().getDecorView(),name);complete(target,name);assertTrue(name+" retains at least48dp",target.getHeight()>=Design.dp(context,48));ViewGroup copy=(ViewGroup)((ViewGroup)target).getChildAt(1);android.widget.TextView title=(android.widget.TextView)copy.getChildAt(0),subtitle=(android.widget.TextView)copy.getChildAt(2);assertEquals(name,title.getText().toString());assertEquals(name+" title is readable on one line",1,title.getLineCount());assertTrue(name+" text has the available row width",title.getWidth()>=Design.dp(context,220));assertEquals(name+" subtitle shares the full column",title.getWidth(),subtitle.getWidth());assertTrue(name+" explanation is below the title",subtitle.getTop()>=title.getBottom());}});capture(first,"supporting-routes");
            click("Breathing rhythm");EchoPeriodsActivity echo=focused(EchoPeriodsActivity.class);assertTrue(device.wait(Until.hasObject(By.text("No rhythm analysis recorded")),5000));assertEquals("Supporting route retains the exact source record",id,echo.getIntent().getLongExtra("record",0));capture(echo,"echo-route");device.pressBack();destroyed(echo);assertSame("Back returns to the same signals owner",first,focused(RecordSignalsActivity.class));assertEquals(id,first.getIntent().getLongExtra("record",0));
            new UiScrollable(new UiSelector().scrollable(true)).scrollToBeginning(6);device.waitForIdle();signalBounds(first,start,end);
            instrumentation.runOnMainSync(()->{RecordChart plot=chart(first.getWindow().getDecorView());assertTrue(plot.performAccessibilityAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD,null));assertTrue("Zero is an actual saved reading",plot.getContentDescription().toString().contains(String.format(Locale.getDefault(),"%.3f",0d)+" measured reading"));assertTrue(plot.getContentDescription().toString().startsWith("Relative echo change at "));assertFalse("Null calibration/no-echo gaps must not become chart bars",plot.performAccessibilityAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD,null));});capture(first,"zero");
            device.pressBack();destroyed(first);first.awaitReaders(5000);focused(RecordReportActivity.class);signals();RecordSignalsActivity reopened=focused(RecordSignalsActivity.class);assertNotSame(first,reopened);signalBounds(reopened,start,end);capture(reopened,"reopened");
            instrumentation.runOnMainSync(()->reopened.startActivity(new Intent(reopened,RecordReportActivity.class).putExtra("record",legacyId).putExtra("visualReview",true).putExtra("verificationLabel",LABEL)));RecordReportActivity legacy=focusedReport(legacyId);assertTrue(device.wait(Until.hasObject(By.text("No classified sound events in this period.")),5000));assertFalse("Unknown historical analysis cannot be called off",device.hasObject(By.text("Sound analysis was off.")));capture(legacy,"legacy-unknown");
            instrumentation.runOnMainSync(()->legacy.startActivity(new Intent(legacy,RecordReportActivity.class).putExtra("record",errorId).putExtra("visualReview",true).putExtra("verificationLabel",LABEL)));RecordReportActivity failed=focusedReport(errorId);assertTrue(device.wait(Until.hasObject(By.text("Sound analysis needs attention.")),5000));assertFalse(device.hasObject(By.text("Sound analysis completed.")));capture(failed,"analysis-error");
            // Suppressing absent metrics must not discard real supplemental measurements.
            // This separate legacy fixture has actual stored values, never a live input port.
            instrumentation.runOnMainSync(()->failed.startActivity(new Intent(failed,RecordSignalsActivity.class).putExtra("record",800L).putExtra("visualReview",true).putExtra("verificationLabel","TEST · isolated supplemental measurements")));
            assertTrue(device.wait(Until.hasObject(By.text("Room noise")),5000));RecordSignalsActivity supplemental=focused(RecordSignalsActivity.class);instrumentation.runOnMainSync(()->{View root=supplemental.getWindow().getDecorView();assertEquals("All saved metric types remain available",3,chartCount(root));for(String metric:new String[]{"Phone movement","Room noise","Room light"})assertNotNull(metric,named(root,metric+" chart. 1 actual readings. Missing intervals are blank. Dense bars average contiguous readings."));});
            try(Store store=new Store(context,database)){assertEquals("Read-only journey preserves every original table value",fingerprint,BackupFingerprint.read(store));assertEquals(raw,store.rows("SELECT * FROM epochs ORDER BY time").toString());RecordEntry entry=Records.get(store,id);assertEquals(SensorProvenance.SONAR,entry.sensor);assertEquals(config,entry.sensorConfig);assertEquals(start,entry.rawStart);assertEquals(end,entry.rawEnd);assertEquals(0,store.rows("SELECT clock_changed FROM sessions WHERE id=?",""+id).get(0).getInt("clock_changed"));List<JSONObject> rows=store.rows("SELECT * FROM epochs WHERE session=? ORDER BY time",""+id);assertTrue(rows.get(0).isNull("movement"));assertEquals("CALIBRATING",rows.get(0).getString("signal_quality"));assertEquals(0,rows.get(1).getDouble("movement"),0);assertEquals("VALID",rows.get(1).getString("signal_quality"));assertTrue(rows.get(2).isNull("movement"));assertEquals("NO_ECHO",rows.get(2).getString("signal_quality"));}
            assertEquals(prefs,Prefs.of(context).getAll());assertFalse(TrackingService.running);assertFalse(AlarmService.active);assertFalse(Prefs.flag(context,"ringing"));
        }catch(Exception|AssertionError error){diagnose(error);throw error;}
        finally{try{instrumentation.runOnMainSync(()->{for(Activity activity:owned)if(!activity.isDestroyed())activity.finish();});instrumentation.waitForIdleSync();for(Activity activity:owned){destroyed(activity);if(activity instanceof RecordReportActivity)((RecordReportActivity)activity).awaitReaders(5000);if(activity instanceof RecordSignalsActivity)((RecordSignalsActivity)activity).awaitReaders(5000);}cleaned=true;assertEquals("No preference changes",prefs,Prefs.of(context).getAll());}finally{app.unregisterActivityLifecycleCallbacks(lifecycle);Records.factory=previous;if(cleaned)assertTrue(context.deleteDatabase(database));}}
    }
}
